// Product Detail + Edit tests (generated by engineering-platform frontend-product-reference asset)
// detail rendering, not-found, error retry, disable flow, edit update.
import { describe, it, expect, vi, beforeEach } from 'vitest';
import { mount, flushPromises } from '@vue/test-utils';
import { createPinia, setActivePinia } from 'pinia';
import { useAuthStore } from '../src/stores/auth';
import { createRouter, createMemoryHistory } from 'vue-router';
import ProductDetailView from '../src/views/product/ProductDetailView.vue';
import ProductEditView from '../src/views/product/ProductEditView.vue';
import { productApi } from '../src/api/product';
import { dictionaryApi } from '../src/api/enterprise';
import type { Product } from '../src/types/product';
import { epStubs, platformStubs } from './stubs';
import ConfirmAction from '../src/components/ConfirmAction.vue';

const stubs = {
  ...epStubs(),
  ...platformStubs(),
  'el-result': { template: '<div><slot name="extra" /><slot /></div>' },
};

const product: Product = {
  id: '2', code: 'PRD-002', name: 'P-SALES-1', status: 'DISABLED', category: 'MECHANICAL',
  departmentId: '2', createdBy: '4', createdAt: '2026-08-15T00:00:00', updatedAt: '2026-08-15T00:00:00',
};

function makeRouter(): ReturnType<typeof createRouter> {
  return createRouter({
    history: createMemoryHistory(),
    routes: [
      { path: '/products/:id', component: ProductDetailView },
      { path: '/products/:id/edit', component: ProductEditView },
      { path: '/products', component: { template: '<div>list</div>' } },
    ],
  });
}

function seed(permissions: string[]): void {
  const pinia = createPinia();
  setActivePinia(pinia);
  const auth = useAuthStore(pinia);
  auth.$patch({ currentUser: { id: '1', username: 'u', departmentId: null, permissions } });
  localStorage.clear();
}

describe('ProductDetailView', () => {
  beforeEach(() => {
    vi.restoreAllMocks();
  });

  it('renders detail sections from real API (not an edit form)', async () => {
    seed(['product:item:read']);
    vi.spyOn(productApi, 'detail').mockResolvedValue(product);
    const router = makeRouter();
    await router.push('/products/2');
    await router.isReady();
    const wrapper = mount(ProductDetailView, { global: { plugins: [router], stubs } });
    await flushPromises();
    expect(productApi.detail).toHaveBeenCalledWith('2');
    expect(wrapper.find('[data-testid="product-detail"]').exists()).toBe(true);
    expect(wrapper.find('[data-testid="detail-code"]').exists()).toBe(true);
  });

  it('shows not-found state for missing/out-of-scope product (404)', async () => {
    seed(['product:item:read']);
    const err = new Error('not found') as Error & { status: number };
    err.status = 404;
    vi.spyOn(productApi, 'detail').mockRejectedValue(err);
    const router = makeRouter();
    await router.push('/products/999');
    await router.isReady();
    const wrapper = mount(ProductDetailView, { global: { plugins: [router], stubs } });
    await flushPromises();
    expect(wrapper.find('[data-testid="product-detail-notfound"]').exists()).toBe(true);
  });

  it('shows error state with retry', async () => {
    seed(['product:item:read']);
    vi.spyOn(productApi, 'detail').mockRejectedValueOnce(new Error('net')).mockResolvedValueOnce(product);
    const router = makeRouter();
    await router.push('/products/2');
    await router.isReady();
    const wrapper = mount(ProductDetailView, { global: { plugins: [router], stubs } });
    await flushPromises();
    expect(wrapper.find('[data-testid="product-detail-error"]').exists()).toBe(true);
    wrapper.find('[data-testid="product-detail-retry"]').trigger('click');
    await flushPromises();
    expect(wrapper.find('[data-testid="product-detail"]').exists()).toBe(true);
  });

  it('disable action hidden without product:item:disable', async () => {
    seed(['product:item:read']);
    const enabled: Product = { ...product, status: 'ENABLED' };
    vi.spyOn(productApi, 'detail').mockResolvedValue(enabled);
    const router = makeRouter();
    await router.push('/products/2');
    await router.isReady();
    const wrapper = mount(ProductDetailView, { global: { plugins: [router], stubs } });
    await flushPromises();
    expect(wrapper.find('[data-testid="product-detail-disable"]').exists()).toBe(false);
  });

  it('disable calls API and refreshes', async () => {
    seed(['product:item:read', 'product:item:disable']);
    const enabled: Product = { ...product, status: 'ENABLED' };
    vi.spyOn(productApi, 'detail').mockResolvedValue(enabled);
    const disableSpy = vi.spyOn(productApi, 'disable').mockResolvedValue({ ...product, status: 'DISABLED' });
    const router = makeRouter();
    await router.push('/products/2');
    await router.isReady();
    const wrapper = mount(ProductDetailView, { global: { plugins: [router], stubs } });
    await flushPromises();
    // ConfirmAction (ElPopconfirm) confirm triggers disable directly
    wrapper.findComponent(ConfirmAction).vm.$emit('confirm');
    await flushPromises();
    expect(disableSpy).toHaveBeenCalledWith('2');
  });
});

describe('ProductEditView', () => {
  beforeEach(() => {
    vi.restoreAllMocks();
  });

  it('loads product and submits update (ownership untouched)', async () => {
    seed(['product:item:read', 'product:item:update']);
    vi.spyOn(productApi, 'detail').mockResolvedValue(product);
    vi.spyOn(dictionaryApi, 'itemsByCode').mockResolvedValue([]);
    const updateSpy = vi.spyOn(productApi, 'update').mockResolvedValue(product);
    const router = makeRouter();
    await router.push('/products/2/edit');
    await router.isReady();
    const wrapper = mount(ProductEditView, { global: { plugins: [router], stubs } });
    await flushPromises();
    expect(wrapper.find('[data-testid="product-edit"]').exists()).toBe(true);
    // fire AppForm submit
    const AppForm = (await import('../src/components/AppForm.vue')).default;
    wrapper.findComponent(AppForm).vm.$emit('submit');
    await flushPromises();
    expect(updateSpy).toHaveBeenCalledWith('2', expect.objectContaining({
      code: 'PRD-002',
      // ownership fields never part of the request body
    }));
    const body = updateSpy.mock.calls[0][1] as unknown as Record<string, unknown>;
    expect(body).not.toHaveProperty('createdBy');
    expect(body).not.toHaveProperty('departmentId');
  });

  it('shows error state when detail load fails', async () => {
    seed(['product:item:read', 'product:item:update']);
    vi.spyOn(productApi, 'detail').mockRejectedValue(new Error('boom'));
    const router = makeRouter();
    await router.push('/products/2/edit');
    await router.isReady();
    const wrapper = mount(ProductEditView, { global: { plugins: [router], stubs } });
    await flushPromises();
    expect(wrapper.find('[data-testid="product-edit-error"]').exists()).toBe(true);
  });
});
